import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as r,c as a,ak as n}from"./chunks/framework.DC-k2h36.js";const i="/projects/esp32Sensor/en/latest/assets/1.jPRKXs2B.webp",s="/projects/esp32Sensor/en/latest/assets/2.CiB5qgLH.webp",l="/projects/esp32Sensor/en/latest/assets/3.DQRfC3Li.webp",c="/projects/esp32Sensor/en/latest/assets/4.ChFyrZs_.webp",y=JSON.parse('{"title":"4. Touch Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4. Touch Sensor.md","filePath":"docs/4. Touch Sensor.md"}'),h={name:"docs/4. Touch Sensor.md"};function d(p,e,u,g,m,_){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_4-touch-sensor" tabindex="-1">4. Touch Sensor <a class="header-anchor" href="#_4-touch-sensor" aria-label="Permalink to &quot;4. Touch Sensor&quot;">​</a></h1><h2 id="_4-1-introduction" tabindex="-1">4.1 Introduction <a class="header-anchor" href="#_4-1-introduction" aria-label="Permalink to &quot;4.1 Introduction&quot;">​</a></h2><p>The touch sensor operates on capacitive sensing principles and can be applied to equipment switch controls, such as controlling lights and doorbell touch buttons.</p><img loading="lazy" height="1156" width="1156" src="'+i+'" class="common_img" style="width:300px;"><h2 id="_4-2-technical-specifications" tabindex="-1">4.2 Technical Specifications <a class="header-anchor" href="#_4-2-technical-specifications" aria-label="Permalink to &quot;4.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Trigger mode</td><td style="text-align:center;">Capacitive touch trigger</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 16.7 mm</td></tr></tbody></table><h2 id="_4-3-hands-on-project" tabindex="-1">4.3 Hands-On Project <a class="header-anchor" href="#_4-3-hands-on-project" aria-label="Permalink to &quot;4.3 Hands-On Project&quot;">​</a></h2><h3 id="_4-3-1-project-overview" tabindex="-1">4.3.1 Project Overview <a class="header-anchor" href="#_4-3-1-project-overview" aria-label="Permalink to &quot;4.3.1 Project Overview&quot;">​</a></h3><p>This project uses the touch sensor and the onboard buzzer of the controller to implement a touch-activated doorbell. When a finger touches the sensor, the buzzer plays note C5 in the background. Releasing the touch sensor silences the buzzer immediately, illustrating the detection logic of the touch sensor.</p><h3 id="_4-3-2-hardware-wiring" tabindex="-1">4.3.2 Hardware Wiring <a class="header-anchor" href="#_4-3-2-hardware-wiring" aria-label="Permalink to &quot;4.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the touch sensor to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="623" src="'+s+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_4-3-3-adding-extensions" tabindex="-1">4.3.3 Adding Extensions <a class="header-anchor" href="#_4-3-3-adding-extensions" aria-label="Permalink to &quot;4.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Touch module</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_4-3-4-complete-program-and-analysis" tabindex="-1">4.3.4 Complete Program and Analysis <a class="header-anchor" href="#_4-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;4.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Upon power-up, the hardware port of the touch sensor is initialized to port P5.</p></li><li><p>Inside the main program loop, the status of the touch sensor is continuously monitored to determine whether touch is triggered:</p><ul><li><p>When touch is triggered, the buzzer plays note C5 continuously in the background.</p></li><li><p>When touch is released, the buzzer turns off, stopping sound output.</p></li></ul></li><li><p>A 0.1 s delay is executed at the end of each loop iteration before repeating the entire touch detection process.</p></li></ol><img loading="lazy" height="581" width="683" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">01 Program Files/04 Touch Sensor.sb3</a>.</strong></p></div><h3 id="_4-3-5-program-upload" tabindex="-1">4.3.5 Program Upload <a class="header-anchor" href="#_4-3-5-program-upload" aria-label="Permalink to &quot;4.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_4-3-6-program-outcome" tabindex="-1">4.3.6 Program Outcome <a class="header-anchor" href="#_4-3-6-program-outcome" aria-label="Permalink to &quot;4.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, touching the touch sensor causes the buzzer to play note C5. Moving the finger away immediately silences the buzzer, delivering an interactive touch doorbell experience.</p>',25)])])}const x=o(h,[["render",d]]);export{y as __pageData,x as default};
